local({
  yy <- as.numeric(date) %% 100
  year <- if_else(yy == 99, 1999, 2000 + yy)
  case_when(group == 7 ~ 1998, !is.na(year) ~ year, .default = modal_within(year, group))
})

local({
  count <- as.numeric(v006)
  two_blocks <- questionnaire_id %in% questionnaire_id[child == "oldest"]
  case_when(count == 0 ~ NA_real_, count == 1 & two_blocks ~ NA_real_, .default = count - 1)
})

local({
  how_much <- as.numeric(v093)
  when_watched <- as.numeric(v094)
  game_limit <- as.numeric(q6i)
  case_when(
    how_much %in% 5 | when_watched %in% 5 | game_limit %in% 2:5 ~ "TRUE",
    how_much %in% 1 | when_watched %in% 1 | game_limit %in% 1 ~ "FALSE",
    .default = NA_character_
  )
})

local({
  items <- cbind(as.numeric(q5a), as.numeric(q6c), as.numeric(q6e), as.numeric(q6f), as.numeric(q6i))
  items[!items %in% 1:5] <- NA
  rowMeans(items)
})

local({
  items <- cbind(as.numeric(q6d), as.numeric(q6g), as.numeric(q6j))
  items[!items %in% 1:5] <- NA
  rowMeans(items)
})
